<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import { api } from '../api';import { ElMessage } from 'element-plus'
const courses=ref<any[]>([]),classes=ref<any[]>([]),jobs=ref<any[]>([]),questions=ref<any[]>([]),config=ref<any>(null),loading=ref(true)
const stats=computed(()=>({courses:courses.value.length,classes:classes.value.length,students:classes.value.reduce((n,x)=>n+Number(x.member_count||0),0),failed:jobs.value.filter(x=>x.status==='failed'||x.analysis_status==='failed').length,pending:jobs.value.filter(x=>x.analysis_status==='review_required').length,questions:questions.value.filter(x=>x.status==='draft').length}))
async function load(){try{[courses.value,classes.value,config.value]=(await Promise.all([api.get('/teacher/courses'),api.get('/teacher/classes'),api.get('/system/student-import-config')])).map(x=>x.data);jobs.value=(await Promise.all(courses.value.map(x=>api.get(`/teacher/courses/${x.course_id}/ingestion-jobs`)))).flatMap(x=>x.data);questions.value=(await Promise.all(courses.value.map(x=>api.get(`/teacher/courses/${x.course_id}/question-bank`)))).flatMap(x=>x.data)}catch(e:any){ElMessage.error(e.response?.data?.detail||'概览加载失败')}finally{loading.value=false}}onMounted(load)
</script>
<template><main class="content dashboard" v-loading="loading"><div class="page-title"><span class="eyebrow">TEACHER DASHBOARD</span><h1>工作台概览</h1><p class="muted">只展示教学建设状态，具体操作请进入对应模块。</p></div><el-alert v-if="config&&!config.configured" title="学生初始密码未配置" :description="`请在 ${config.config_path} 中设置 ZHIJIAO_STUDENT_DEFAULT_PASSWORD`" type="error" :closable="false"/><el-alert v-else-if="config?.security_level==='weak'" title="学生统一初始密码强度较弱" description="允许继续导入，但建议尽快提升密码强度；学生首次登录仍必须修改密码。" type="warning" :closable="false"/><section class="metric-grid six"><el-card shadow="never"><span>共享课程</span><b>{{stats.courses}}</b></el-card><el-card shadow="never"><span>教学班</span><b>{{stats.classes}}</b></el-card><el-card shadow="never"><span>授权学生</span><b>{{stats.students}}</b></el-card><el-card shadow="never"><span>解析/分析失败</span><b>{{stats.failed}}</b></el-card><el-card shadow="never"><span>待审核知识资料</span><b>{{stats.pending}}</b></el-card><el-card shadow="never"><span>待审核习题</span><b>{{stats.questions}}</b></el-card></section><el-row :gutter="18"><el-col :span="12"><el-card shadow="never"><template #header><b>知识建设提醒</b></template><p>待审核资料：{{stats.pending}}</p><p>失败任务：{{stats.failed}}</p><el-button type="primary" @click="$router.push('/knowledge')">进入知识中心</el-button></el-card></el-col><el-col :span="12"><el-card shadow="never"><template #header><b>教学班提醒</b></template><p>当前共 {{stats.classes}} 个教学班、{{stats.students}} 名授权学生。</p><el-button @click="$router.push('/teaching')">管理课程与教学班</el-button></el-card></el-col></el-row></main></template>
